  $p=[ordered]@{provider='supabase_postgres';projectRef=Get-ApprovalText $ConfirmProjectRef '^[a-z]{20}$' 'ROLLBACK_PROJECT_REQUIRED';host=Get-ApprovalText $ConfirmDatabaseHost '^(?:db\.[a-z]{20}\.supabase\.co|[a-z0-9-]+\.pooler\.supabase\.com)$' 'ROLLBACK_HOST_REQUIRED';port=5432;databaseName=Get-ApprovalText $ConfirmDatabaseName '^[a-z][a-z0-9_]{0,62}$' 'ROLLBACK_DATABASE_REQUIRED';databaseSchema=Get-ApprovalText $ConfirmDatabaseSchema '^[a-z][a-z0-9_]{0,62}$' 'ROLLBACK_SCHEMA_REQUIRED';databaseUser=Get-ApprovalText $ConfirmDatabaseUser '^[a-z][a-z0-9_]{0,62}$' 'ROLLBACK_DATABASE_USER_REQUIRED';runtimeConfigPath=Get-ApprovalPath $RuntimeConfigPath 'ROLLBACK_RUNTIME_REQUIRED';runtimeConfigSha256=Get-ApprovalHash $ExpectedRuntimeConfigSha256 'ROLLBACK_RUNTIME_HASH_REQUIRED';baselinePath=Get-ApprovalPath $LegacyBaselineEvidencePath 'ROLLBACK_BASELINE_REQUIRED';baselineSha256=Get-ApprovalHash $ExpectedLegacyBaselineEvidenceSha256 'ROLLBACK_BASELINE_HASH_REQUIRED';migrationJournalPath=Get-ApprovalPath $MigrationJournalPath 'ROLLBACK_JOURNAL_REQUIRED';migrationJournalSha256=Get-ApprovalHash $ExpectedMigrationJournalSha256 'ROLLBACK_JOURNAL_HASH_REQUIRED';maintenanceFlagPath=Get-ApprovalPath $MaintenanceFlagPath 'ROLLBACK_MAINTENANCE_REQUIRED';maintenanceFlagSha256=Get-ApprovalHash $ExpectedMaintenanceFlagSha256 'ROLLBACK_MAINTENANCE_HASH_REQUIRED';drainStatePath=Get-ApprovalPath $DrainStatePath 'ROLLBACK_DRAIN_REQUIRED';drainStateSha256=Get-ApprovalHash $ExpectedDrainStateSha256 'ROLLBACK_DRAIN_HASH_REQUIRED';backupEvidencePath=Get-ApprovalPath $BackupEvidencePath 'ROLLBACK_BACKUP_EVIDENCE_REQUIRED';backupEvidenceSha256=Get-ApprovalHash $ExpectedBackupEvidenceSha256 'ROLLBACK_BACKUP_EVIDENCE_HASH_REQUIRED';backupPublicKeyPath=Get-ApprovalPath $BackupReceiptPublicKeyPath 'ROLLBACK_BACKUP_KEY_REQUIRED';backupPublicKeySha256=Get-ApprovalHash $ExpectedBackupReceiptPublicKeySha256 'ROLLBACK_BACKUP_KEY_HASH_REQUIRED';backupDirectory=Get-ApprovalPath $BackupDirectory 'ROLLBACK_BACKUP_DIRECTORY_REQUIRED';integrityKeyPath=Get-ApprovalPath $BackupIntegrityKeyFile 'ROLLBACK_INTEGRITY_KEY_REQUIRED';integrityKeySha256=Get-ApprovalHash $ExpectedBackupIntegrityKeySha256 'ROLLBACK_INTEGRITY_KEY_HASH_REQUIRED';nodePath=Get-ApprovalPath $NodePath 'ROLLBACK_NODE_REQUIRED';nodeSha256=Get-ApprovalHash $ExpectedNodeSha256 'ROLLBACK_NODE_HASH_REQUIRED';verifierPath=Get-ApprovalPath $AttestationVerifierPath 'ROLLBACK_VERIFIER_REQUIRED';verifierSha256=Get-ApprovalHash $ExpectedAttestationVerifierSha256 'ROLLBACK_VERIFIER_HASH_REQUIRED';psqlPath=Get-ApprovalPath $PsqlPath 'ROLLBACK_PSQL_REQUIRED';psqlSha256=Get-ApprovalHash $ExpectedPsqlSha256 'ROLLBACK_PSQL_HASH_REQUIRED';pgRestorePath=Get-ApprovalPath $PgRestorePath 'ROLLBACK_PGRESTORE_REQUIRED';pgRestoreSha256=Get-ApprovalHash $ExpectedPgRestoreSha256 'ROLLBACK_PGRESTORE_HASH_REQUIRED';pgPassPath=Get-ApprovalPath $PgPassFile 'ROLLBACK_PGPASS_REQUIRED';pgPassSha256=Get-ApprovalHash $ExpectedPgPassSha256 'ROLLBACK_PGPASS_HASH_REQUIRED';caPath=Get-ApprovalPath $CaCertificatePath 'ROLLBACK_CA_REQUIRED';caSha256=Get-ApprovalHash $ExpectedCaCertificateSha256 'ROLLBACK_CA_HASH_REQUIRED';filesystemEvidencePath=Get-ApprovalPath $FileSystemEvidencePath 'ROLLBACK_FS_REQUIRED';filesystemEvidenceSha256=Get-ApprovalHash $ExpectedFileSystemEvidenceSha256 'ROLLBACK_FS_HASH_REQUIRED';evidenceOutputPath=Get-ApprovalPath $EvidenceOutputPath 'ROLLBACK_EVIDENCE_OUTPUT_REQUIRED';maximumRestoreDurationSeconds=$MaximumRestoreDurationSeconds;maximumDatabaseDumpBytes=$MaximumDatabaseDumpBytes;maximumChildOutputBytes=$MaximumChildOutputBytes}
  if($IntendedAction-eq'Apply'){$p.signerPath=Get-ApprovalPath $AttestationSignerPath 'ROLLBACK_SIGNER_REQUIRED';$p.signerSha256=Get-ApprovalHash $ExpectedAttestationSignerSha256 'ROLLBACK_SIGNER_HASH_REQUIRED';$p.restorePrivateKeyPath=Get-ApprovalPath $RestoreReceiptPrivateKeyPath 'ROLLBACK_PRIVATE_KEY_REQUIRED';$p.restorePrivateKeySha256=Get-ApprovalHash $ExpectedRestoreReceiptPrivateKeySha256 'ROLLBACK_PRIVATE_KEY_HASH_REQUIRED'}else{$p.evidenceSha256=Get-ApprovalHash $ExpectedEvidenceSha256 'ROLLBACK_EVIDENCE_HASH_REQUIRED';$p.restorePublicKeyPath=Get-ApprovalPath $RestoreReceiptPublicKeyPath 'ROLLBACK_PUBLIC_KEY_REQUIRED';$p.restorePublicKeySha256=Get-ApprovalHash $ExpectedRestoreReceiptPublicKeySha256 'ROLLBACK_PUBLIC_KEY_HASH_REQUIRED'}
  New-ApprovalPlan $PSCommandPath $IntendedAction $p "Exact existing Supabase target $ConfirmProjectRef/$ConfirmDatabaseHost`:5432/$ConfirmDatabaseName schema $ConfirmDatabaseSchema" 'While maintenance/drain and legacy quiesce remain active, restores the signed pre-change database chain and proves KPI plus legacy local-storage hashes' 'If verification fails, keep maintenance and writers stopped; execute only a new approved restore/repair plan. Exact legacy restart is a separate approved Manage-LegacyQuiesce Rollback plan'
}
if($Action-eq'Plan'){New-RollbackPlan $PlannedAction|ConvertTo-Json -Depth 12;exit 0};$intended=if($Action-eq'Apply'){'Apply'}else{'VerifyEvidence'};Assert-ApprovedPlan (New-RollbackPlan $intended) ([bool]$Approved) $ApprovedPlanSha256
$runtime=Existing $RuntimeConfigPath $false 'ROLLBACK_RUNTIME_NOT_FOUND';$baselinePath=Existing $LegacyBaselineEvidencePath $false 'ROLLBACK_BASELINE_NOT_FOUND';$journalPath=Existing $MigrationJournalPath $false 'ROLLBACK_JOURNAL_NOT_FOUND';$maintenancePath=Existing $MaintenanceFlagPath $false 'ROLLBACK_MAINTENANCE_NOT_FOUND';$drainPath=Existing $DrainStatePath $false 'ROLLBACK_DRAIN_NOT_FOUND';$backupEvidence=Existing $BackupEvidencePath $false 'ROLLBACK_BACKUP_EVIDENCE_NOT_FOUND';$backupPublic=Existing $BackupReceiptPublicKeyPath $false 'ROLLBACK_BACKUP_PUBLIC_KEY_NOT_FOUND';$backupRoot=Existing $BackupDirectory $true 'ROLLBACK_BACKUP_DIRECTORY_NOT_FOUND';$integrityKey=Existing $BackupIntegrityKeyFile $false 'ROLLBACK_INTEGRITY_KEY_NOT_FOUND';$node=Existing $NodePath $false 'ROLLBACK_NODE_NOT_FOUND';$verifier=Existing $AttestationVerifierPath $false 'ROLLBACK_VERIFIER_NOT_FOUND';$psql=Existing $PsqlPath $false 'ROLLBACK_PSQL_NOT_FOUND';$pgRestore=Existing $PgRestorePath $false 'ROLLBACK_PGRESTORE_NOT_FOUND';$pgpass=Existing $PgPassFile $false 'ROLLBACK_PGPASS_NOT_FOUND';$ca=Existing $CaCertificatePath $false 'ROLLBACK_CA_NOT_FOUND';$fsPath=Existing $FileSystemEvidencePath $false 'ROLLBACK_FS_NOT_FOUND'
foreach($v in @(@($runtime,$ExpectedRuntimeConfigSha256,'ROLLBACK_RUNTIME_HASH_MISMATCH'),@($baselinePath,$ExpectedLegacyBaselineEvidenceSha256,'ROLLBACK_BASELINE_HASH_MISMATCH'),@($journalPath,$ExpectedMigrationJournalSha256,'ROLLBACK_JOURNAL_HASH_MISMATCH'),@($maintenancePath,$ExpectedMaintenanceFlagSha256,'ROLLBACK_MAINTENANCE_HASH_MISMATCH'),@($drainPath,$ExpectedDrainStateSha256,'ROLLBACK_DRAIN_HASH_MISMATCH'),@($backupEvidence,$ExpectedBackupEvidenceSha256,'ROLLBACK_BACKUP_EVIDENCE_HASH_MISMATCH'),@($backupPublic,$ExpectedBackupReceiptPublicKeySha256,'ROLLBACK_BACKUP_KEY_HASH_MISMATCH'),@($integrityKey,$ExpectedBackupIntegrityKeySha256,'ROLLBACK_INTEGRITY_KEY_HASH_MISMATCH'),@($node,$ExpectedNodeSha256,'ROLLBACK_NODE_HASH_MISMATCH'),@($verifier,$ExpectedAttestationVerifierSha256,'ROLLBACK_VERIFIER_HASH_MISMATCH'),@($psql,$ExpectedPsqlSha256,'ROLLBACK_PSQL_HASH_MISMATCH'),@($pgRestore,$ExpectedPgRestoreSha256,'ROLLBACK_PGRESTORE_HASH_MISMATCH'),@($pgpass,$ExpectedPgPassSha256,'ROLLBACK_PGPASS_HASH_MISMATCH'),@($ca,$ExpectedCaCertificateSha256,'ROLLBACK_CA_HASH_MISMATCH'),@($fsPath,$ExpectedFileSystemEvidenceSha256,'ROLLBACK_FS_HASH_MISMATCH'))){AssertHash $v[0] $v[1] $v[2]}
$config=Get-Content -Raw -LiteralPath $runtime|ConvertFrom-Json;$db=$config.database;if($db.provider-cne'supabase_postgres'-or$db.projectRef-cne$ConfirmProjectRef-or$db.host-cne$ConfirmDatabaseHost-or$db.port-ne5432-or$db.name-cne$ConfirmDatabaseName-or$db.schema-cne$ConfirmDatabaseSchema-or$db.migrationUser-cne$ConfirmDatabaseUser){throw 'ROLLBACK_DATABASE_TARGET_MISMATCH'}
$maintenance=Get-Content -Raw -LiteralPath $maintenancePath|ConvertFrom-Json;$drain=Get-Content -Raw -LiteralPath $drainPath|ConvertFrom-Json;if($maintenance.version-ne1-or-not$maintenance.enabled-or$maintenance.releaseId-cne$config.release.id-or$drain.version-ne1-or$drain.result-cne'DRAINED'-or$drain.activeRequests-ne0-or-not(Get-Process -Id ([int]$drain.processId) -ErrorAction SilentlyContinue)-or@(Get-NetTCPConnection -State Listen -LocalPort 3100,4100 -ErrorAction SilentlyContinue).Count){throw 'ROLLBACK_MAINTENANCE_DRAIN_OR_QUIESCE_REJECTED'}
$baseline=Get-Content -Raw -LiteralPath $baselinePath|ConvertFrom-Json;$journal=Get-Content -Raw -LiteralPath $journalPath|ConvertFrom-Json;if($baseline.version-ne3-or$baseline.proofType-cne'legacy-running-baseline'-or$baseline.migrationDigest-notmatch'^[0-9a-f]{64}$'-or($journal.result-cne'APPLIED_PENDING_BOUNDARY'-and$journal.result-cne'APPLIED')){throw 'ROLLBACK_BASELINE_OR_JOURNAL_REJECTED'}
&$node $verifier $backupPublic $backupEvidence 'backup-latest' 2>$null|Out-Null;if($LASTEXITCODE-ne0){throw 'ROLLBACK_BACKUP_SIGNATURE_REJECTED'};$receipt=Get-Content -Raw -LiteralPath $backupEvidence|ConvertFrom-Json;if($receipt.attestationType-cne'backup-latest'-or$receipt.result-cne'COMPLETE'-or$receipt.backupMode-cne'LEGACY_BASELINE'-or$receipt.legacyBaselineSha256-cne(Hash $baselinePath)-or$receipt.databaseProjectRef-cne$ConfirmProjectRef-or$receipt.databaseHost-cne$ConfirmDatabaseHost-or$receipt.databaseName-cne$ConfirmDatabaseName-or$receipt.databaseSchema-cne$ConfirmDatabaseSchema){throw 'ROLLBACK_BACKUP_CHAIN_REJECTED'}
$manifestPath=Existing (Join-Path $backupRoot 'backup-manifest.json') $false 'ROLLBACK_MANIFEST_NOT_FOUND';$dumpPath=Existing (Join-Path $backupRoot 'database.dump') $false 'ROLLBACK_DUMP_NOT_FOUND';if((Hash $manifestPath)-cne$receipt.manifestSha256){throw 'ROLLBACK_MANIFEST_HASH_MISMATCH'};$manifest=Get-Content -Raw -LiteralPath $manifestPath|ConvertFrom-Json;if($manifest.version-ne6-or$manifest.backupId-cne$receipt.backupId-or$manifest.databaseDumpBytes-gt$MaximumDatabaseDumpBytes-or(Get-Item -LiteralPath $dumpPath).Length-ne$manifest.databaseDumpBytes-or(Hash $dumpPath)-cne$manifest.databaseDumpSha256-or(Hash $integrityKey)-cne$manifest.integrityKeyId-or(Hmac $integrityKey (SignatureInput $manifest))-cne$manifest.integritySignature){throw 'ROLLBACK_BACKUP_INTEGRITY_REJECTED'}
$fs=Get-Content -Raw -LiteralPath $fsPath|ConvertFrom-Json;if($fs.result-ne'PASS'-or-not$fs.exactAcl-or@(@($node,$verifier,$psql,$pgRestore)|Where-Object{-not(Under $_ $fs.classRoots.SHARED_RUNTIME)}).Count-or-not(Under $pgpass $fs.classRoots.ADMIN_ONLY)-or-not(Under $integrityKey $fs.classRoots.BACKUP_ONLY)-or-not(Under $EvidenceOutputPath $fs.classRoots.ADMIN_EVIDENCE)){throw 'ROLLBACK_FILESYSTEM_BOUNDARY_REJECTED'}
$connectionUser=if($db.connectionMode-eq'session_pooler'){"$($db.migrationUser).$($db.projectRef)"}else{[string]$db.migrationUser};$environment=@{PGPASSFILE=$pgpass;PGSSLMODE='verify-full';PGSSLROOTCERT=$ca;PGCONNECT_TIMEOUT='15';PGOPTIONS='-c lock_timeout=30000 -c statement_timeout=3600000 -c idle_in_transaction_session_timeout=60000';PGAPPNAME='meta-ads-legacy-rollback'};$base=@("--host=$($db.host)",'--port=5432',"--username=$connectionUser","--dbname=$($db.name)",'--no-password')
if($Action-eq'Apply'){
  if(Test-Path -LiteralPath $EvidenceOutputPath){throw 'ROLLBACK_EVIDENCE_ALREADY_EXISTS'};$signer=Existing $AttestationSignerPath $false 'ROLLBACK_SIGNER_NOT_FOUND';$private=Existing $RestoreReceiptPrivateKeyPath $false 'ROLLBACK_PRIVATE_KEY_NOT_FOUND';AssertHash $signer $ExpectedAttestationSignerSha256 'ROLLBACK_SIGNER_HASH_MISMATCH';AssertHash $private $ExpectedRestoreReceiptPrivateKeySha256 'ROLLBACK_PRIVATE_KEY_HASH_MISMATCH';if(-not(Under $signer $fs.classRoots.SHARED_RUNTIME)-or-not(Under $private $fs.classRoots.ADMIN_ONLY)){throw 'ROLLBACK_SIGNER_BOUNDARY_REJECTED'}
  $quotedSchema='"'+$ConfirmDatabaseSchema.Replace('"','""')+'"';[void](Invoke-Bounded $psql ($base+@('--set=ON_ERROR_STOP=1',"--command=DROP SCHEMA IF EXISTS $quotedSchema CASCADE; CREATE SCHEMA $quotedSchema;")) $environment 'ROLLBACK_SCHEMA_RESET');[void](Invoke-Bounded $pgRestore @("--host=$($db.host)",'--port=5432',"--username=$connectionUser","--dbname=$($db.name)",'--no-password','--exit-on-error','--no-owner','--no-privileges',"--schema=$ConfirmDatabaseSchema",$dumpPath) $environment 'ROLLBACK_PG_RESTORE')
  $kpi=Invoke-Bounded $psql ($base+@('--tuples-only','--no-align','--set=ON_ERROR_STOP=1',"--command=SET search_path TO $quotedSchema; $(KpiSql)")) $environment 'ROLLBACK_KPI_VERIFY';if((TextHash $kpi)-cne$manifest.businessKpiDigest){throw 'ROLLBACK_KPI_MISMATCH'};$storageDigest=TextHash (@("uploads=$(InventoryDigest ([string]$baseline.legacyUploadsRoot))","reports=$(InventoryDigest ([string]$baseline.legacyReportsRoot))")-join"`n");if($storageDigest-cne$baseline.storageInventoryDigest){throw 'ROLLBACK_STORAGE_HASH_MISMATCH'}
